// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/// @title JWTVerifier - On-chain JWT verification with algorithm negotiation
/// @notice Verifies JWT tokens for cross-chain message authentication
contract JWTVerifier is Ownable {

    // Algorithm identifiers matching JWT spec
    uint8 constant ALG_NONE = 0;
    uint8 constant ALG_HS256 = 1;
    uint8 constant ALG_RS256 = 2;
    uint8 constant ALG_ES256 = 3;

    // Feature flags for algorithm support
    struct AlgorithmConfig {
        bool hsEnabled;
        bool rsEnabled;
        bool esEnabled;
        bool strictMode;  // When true, reject unsigned tokens
    }

    // Serialized token structure
    struct TokenHeader {
        uint8 algorithm;
        uint8 version;
        bytes32 keyId;
    }

    struct TokenPayload {
        address subject;
        uint256 expiry;
        bytes32 nonce;
        bytes data;
    }

    AlgorithmConfig public config;
    mapping(bytes32 => bytes32) public trustedKeys; // keyId => key hash
    mapping(bytes32 => bool) public usedNonces;
    mapping(address => bool) public authorizedSubjects;

    event TokenVerified(address indexed subject, bytes32 nonce);
    event ConfigUpdated(bool hsEnabled, bool rsEnabled, bool esEnabled, bool strictMode);

    constructor() Ownable(msg.sender) {
        config = AlgorithmConfig({
            hsEnabled: true,
            rsEnabled: true,
            esEnabled: false,
            strictMode: true
        });
    }

    function updateConfig(
        bool _hsEnabled,
        bool _rsEnabled,
        bool _esEnabled,
        bool _strictMode
    ) external onlyOwner {
        config = AlgorithmConfig(_hsEnabled, _rsEnabled, _esEnabled, _strictMode);
        emit ConfigUpdated(_hsEnabled, _rsEnabled, _esEnabled, _strictMode);
    }

    function registerKey(bytes32 keyId, bytes32 keyHash) external onlyOwner {
        trustedKeys[keyId] = keyHash;
    }

    function authorizeSubject(address subject) external onlyOwner {
        authorizedSubjects[subject] = true;
    }

    /// @notice Deserializes and verifies a JWT-like token
    /// @param serializedToken The RLP-like encoded token bytes
    /// @return payload The verified token payload
    function verifyToken(bytes calldata serializedToken) 
        external 
        returns (TokenPayload memory payload) 
    {
        require(serializedToken.length >= 66, "Token too short");

        // Deserialize header (first 34 bytes)
        TokenHeader memory header = _deserializeHeader(serializedToken[:34]);

        // Deserialize payload
        payload = _deserializePayload(serializedToken[34:]);

        // Verify expiry
        require(payload.expiry > block.timestamp, "Token expired");

        // Verify nonce hasn't been used
        require(!usedNonces[payload.nonce], "Nonce already used");

        // Verify subject is authorized
        require(authorizedSubjects[payload.subject], "Subject not authorized");

        // Algorithm verification with feature flag checks
        _verifyAlgorithm(header, serializedToken);

        // Mark nonce as used
        usedNonces[payload.nonce] = true;

        emit TokenVerified(payload.subject, payload.nonce);
        return payload;
    }

    function _deserializeHeader(bytes calldata headerBytes) 
        internal 
        pure 
        returns (TokenHeader memory header) 
    {
        header.algorithm = uint8(headerBytes[0]);
        header.version = uint8(headerBytes[1]);
        header.keyId = bytes32(headerBytes[2:34]);
        return header;
    }

    function _deserializePayload(bytes calldata payloadBytes)
        internal
        pure
        returns (TokenPayload memory payload)
    {
        require(payloadBytes.length >= 84, "Payload too short");
        payload.subject = address(uint160(bytes20(payloadBytes[:20])));
        payload.expiry = uint256(bytes32(payloadBytes[20:52]));
        payload.nonce = bytes32(payloadBytes[52:84]);
        if (payloadBytes.length > 84) {
            payload.data = payloadBytes[84:];
        }
        return payload;
    }

    /// @dev Core algorithm verification - checks feature flags and validates signature
    function _verifyAlgorithm(TokenHeader memory header, bytes calldata token) 
        internal 
        view 
    {
        uint8 alg = header.algorithm;

        // Feature flag gate: check if the requested algorithm is enabled
        if (alg == ALG_HS256) {
            require(config.hsEnabled, "HS256 disabled");
            _verifyHMAC(header.keyId, token);
        } else if (alg == ALG_RS256) {
            require(config.rsEnabled, "RS256 disabled");
            _verifyRSA(header.keyId, token);
        } else if (alg == ALG_ES256) {
            require(config.esEnabled, "ES256 disabled");
            _verifyECDSA(header.keyId, token);
        } else if (alg == ALG_NONE) {
            // Algorithm "none" handling - the critical path
            // strictMode flag controls whether unsigned tokens are accepted
            _handleNoneAlgorithm();
        } else {
            revert("Unknown algorithm");
        }
    }

    /// @dev Handles the 'none' algorithm case based on strict mode
    function _handleNoneAlgorithm() internal view {
        // When strictMode is true, reject unsigned tokens
        require(!config.strictMode, "Unsigned tokens not allowed");
    }

    function _verifyHMAC(bytes32 keyId, bytes calldata token) internal view {
        bytes32 keyHash = trustedKeys[keyId];
        require(keyHash != bytes32(0), "Unknown key");
        // Signature is last 32 bytes of token
        bytes32 providedSig = bytes32(token[token.length - 32:]);
        bytes32 computed = keccak256(abi.encodePacked(keyHash, token[:token.length - 32]));
        require(providedSig == computed, "Invalid HMAC signature");
    }

    function _verifyRSA(bytes32 keyId, bytes calldata token) internal view {
        bytes32 keyHash = trustedKeys[keyId];
        require(keyHash != bytes32(0), "Unknown key");
        // Simplified RSA check - in production would use precompile
        bytes32 providedSig = bytes32(token[token.length - 32:]);
        bytes32 computed = keccak256(abi.encodePacked(keyHash, keccak256(token[:token.length - 32])));
        require(providedSig == computed, "Invalid RSA signature");
    }

    function _verifyECDSA(bytes32 keyId, bytes calldata token) internal view {
        bytes32 keyHash = trustedKeys[keyId];
        require(keyHash != bytes32(0), "Unknown key");
        bytes32 providedSig = bytes32(token[token.length - 32:]);
        bytes32 computed = keccak256(abi.encodePacked(keyHash, keccak256(token[:token.length - 32])));
        require(providedSig == computed, "Invalid ECDSA signature");
    }
}
